#include <Cellerator/compiler/backend/nvcc/implement_nvcc_option_and_architecture_mapping_v1.hh>
#include <algorithm>
namespace cellerator::compiler::backend::nvcc::v1 {
std::optional<std::vector<std::string>> make_nvcc_argv(const nvcc_options&o,option_status*s) noexcept{auto set=[&](auto v){if(s)*s=v;};if(o.real_architectures.empty()&&o.virtual_architectures.empty()){set(option_status::missing_architecture);return{};}if(o.cxx_standard!=17){set(option_status::invalid_standard);return{};}if(o.optimization>3){set(option_status::invalid_optimization);return{};}auto valid=[](auto a){return a>=50&&a<=999;};for(auto a:o.real_architectures)if(!valid(a)){set(option_status::unsupported_architecture);return{};}for(auto a:o.virtual_architectures)if(!valid(a)){set(option_status::unsupported_architecture);return{};}for(const auto&x:o.user_options)if(x.rfind("-arch",0)==0||x.rfind("-gencode",0)==0){set(option_status::unsafe_override);return{};}auto real=o.real_architectures;auto virt=o.virtual_architectures;auto libs=o.libraries;auto user=o.user_options;std::sort(real.begin(),real.end());std::sort(virt.begin(),virt.end());std::sort(libs.begin(),libs.end());std::sort(user.begin(),user.end());std::vector<std::string>a{"nvcc","-std=c++17","-O"+std::to_string(o.optimization),"-ccbin",o.host_compiler};if(o.debug)a.push_back("-G");if(o.line_info)a.push_back("-lineinfo");if(o.rdc)a.push_back("-rdc=true");for(auto x:real)a.push_back("-gencode=arch=compute_"+std::to_string(x)+",code=sm_"+std::to_string(x));for(auto x:virt)a.push_back("-gencode=arch=compute_"+std::to_string(x)+",code=compute_"+std::to_string(x));for(const auto&x:libs)a.push_back("-l"+x);a.insert(a.end(),user.begin(),user.end());set(option_status::ok);return a;}
}
